INSERT INTO `sources` (`id`, `url`, `descript`) VALUES
(1, 'https://github.com/c0xffee/Engnima', '最原始的資料源頭機構名稱：中華民國大學入學考試中心（大考中心）。原始文件：官方頒布的《高中英文參考詞彙表》。💻 技術社群的開源源頭（GitHub）大考中心官方只提供 PDF 檔，而你看到的這個特定檔名 7000vocs.csv，是來自 GitHub 上一位名叫 c0xffee 的台灣開發者 Engnima 專案中的 7000vocs.csv 檔案。收錄行數：該開源檔案共有 11,344 行 數據（內含單字、不同詞性的拆分定義）。檔案格式：標準的 CSV 格式（逗號分隔值），內容結構主要為 單字,詞性,中文翻譯。專案背景：這位開發者當年為了製作英文拼字遊戲或背單字專案（Engnima），手動或透過程式將大考中心的 PDF 轉檔、清洗並格式化成這個 CSV 檔，隨後被網路上許多製作 Anki 字卡、Quizlet、LINE 機器人的學生與工程師大量複製、Fork 或引用。');

